import {
    readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, statSync, appendFileSync,
} from "node:fs";
import { execFileSync, spawnSync } from "node:child_process";
import { basename, dirname, join, relative, resolve, sep } from "node:path";
import { ChatOpenAI } from "@langchain/openai";
import { Annotation, StateGraph, START, END, MemorySaver, interrupt } from "@langchain/langgraph";

/* ───────────────────────────── Config ───────────────────────────── */

// Target project generated by the agents (a git repo is created inside if missing)
const WORKDIR = resolve(process.env.PROJECT_DIR ?? "./workspace");
// Command used to run the tests written by the QA agent
const TEST_COMMAND = process.env.TEST_COMMAND ?? "npm test";
const MAX_REJECTIONS = 3;
// Character budgets (16k-token context): keep room for the system prompt and the answer
const DOC_BUDGET = 40000;
const SOURCE_BUDGET = 200000;

mkdirSync(WORKDIR, { recursive: true });

const llm = new ChatOpenAI({
    model: process.env.DEEPSEEK_MODEL ?? "DeepSeek-V4.1-Flash-1017",
    temperature: 0.2,
    maxTokens: 32000,
    openAIApiKey: process.env.DEEPSEEK_API_KEY,
    configuration: {
        baseURL: "https://api.deepseek.com/v1",
    },
});

const prompt = (name: string) =>
    readFileSync(new URL(`./agent_systems/${name}.md`, import.meta.url), "utf-8");
const AgentPO = prompt("agent_po");
const AgentGIT = prompt("agent_git");
const AgentArchitect = prompt("agent_architect");
const AgentBackend = prompt("agent_backend");
const AgentFrontend = prompt("agent_frontend");
const AgentCyber = prompt("agent_cyber");
const AgentQaTests = prompt("agent_qa_tests");

// Appended to every agent system prompt: the file/status convention the orchestrator parses
const OUTPUT_RULES = `OUTPUT FORMAT (mandatory, applies to every file you produce):
- Emit each file as a line "### FILE: relative/path" followed by its content inside a fenced block that uses FOUR backticks (\`\`\`\`).
- Paths are relative to the project root. Never write outside it.
- After all files, finish with the JSON status object alone on the last line, without code fence.`;

/* ───────────────────────────── Types & State ───────────────────────────── */

type Defect = { id?: string; severity?: string; target_agent?: string; file?: string; summary?: string };
type Payload = { status: string; defects: Defect[] };

const last = <T>(def: () => T) => Annotation<T>({ reducer: (_a, b) => b, default: def });

const State = Annotation.Root({
    input: Annotation<string>(),
    humanFeedback: last(() => ""),
    status: last(() => ""),
    defects: last<Defect[]>(() => []),
    iteration: last(() => 0), // number of rejections issued so far
    remediationTarget: last(() => "none"), // Backend | Frontend | Architect | none
    route: last(() => ""), // next node chosen by the node that just ran
    logs: Annotation<string[]>({
        reducer: (ancien, nouveau) => [...ancien, ...nouveau],
        default: () => [],
    }),
});
type S = typeof State.State;

const log = (m: string) => console.log(`[${new Date().toISOString().slice(11, 19)}] ${m}`);

/* ───────────────────────────── Files ───────────────────────────── */

function safePath(rel: string): string | null {
    const abs = resolve(WORKDIR, rel.trim());
    if (abs !== WORKDIR && !abs.startsWith(WORKDIR + sep)) return null;
    if (relative(WORKDIR, abs).split(sep)[0] === ".git") return null;
    return abs;
}

// Write every "### FILE: path" block found in an agent answer; returns written paths
function writeFilesFromOutput(out: string): string[] {
    const written: string[] = [];
    const re = /###\s*FILE:\s*(.+?)\s*\n(`{3,})[^\n]*\n([\s\S]*?)\n\2[ \t]*(?=\n|$)/g;
    for (const m of out.matchAll(re)) {
        const rel = m[1];
        const body = m[3];
        if (!rel || body === undefined) continue;
        const abs = safePath(rel.replace(/^`+|`+$/g, ""));
        if (!abs) {
            log(`ignored unsafe path: ${rel}`);
            continue;
        }
        mkdirSync(dirname(abs), { recursive: true });
        writeFileSync(abs, body.endsWith("\n") ? body : body + "\n", "utf-8");
        written.push(relative(WORKDIR, abs));
    }
    return written;
}

function readDocs(paths: string[], maxEach = DOC_BUDGET): string {
    return paths
        .map((p) => {
            const abs = safePath(p);
            if (!abs || !existsSync(abs)) return "";
            let t = readFileSync(abs, "utf-8");
            if (t.length > maxEach) t = t.slice(0, maxEach) + "\n[...truncated]";
            return `=== ${p} ===\n${t}`;
        })
        .filter(Boolean)
        .join("\n\n");
}

const SKIP_DIRS = new Set(["node_modules", ".git", "dist", "build", "coverage", ".next", "docs", ".venv", "__pycache__"]);
const TEXT_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|json|py|html|css|scss|sql|prisma|vue|svelte|ya?ml)$/i;
const SKIP_FILES = /(package-lock\.json|pnpm-lock\.yaml|yarn\.lock)$/;

function listSource(dir = WORKDIR, out: string[] = []): string[] {
    for (const name of readdirSync(dir).sort()) {
        const abs = join(dir, name);
        const st = statSync(abs);
        if (st.isDirectory()) {
            if (!SKIP_DIRS.has(name)) listSource(abs, out);
        } else if (TEXT_EXT.test(name) && !SKIP_FILES.test(name) && st.size < 60_000) {
            out.push(abs);
        }
    }
    return out;
}

function readSource(budget = SOURCE_BUDGET): string {
    let used = 0;
    let omitted = 0;
    const parts: string[] = [];
    for (const f of listSource()) {
        const text = `=== ${relative(WORKDIR, f)} ===\n${readFileSync(f, "utf-8")}`;
        if (used + text.length > budget) {
            omitted++;
            continue;
        }
        used += text.length;
        parts.push(text);
    }
    if (omitted) parts.push(`[${omitted} source file(s) omitted: context budget reached]`);
    return parts.join("\n\n");
}

/* ───────────────────────────── Shell, scanners, tests ───────────────────────────── */

function sh(cmd: string, cwd: string, timeout = 180_000): { code: number | null; out: string } {
    const r = spawnSync(cmd, { shell: true, cwd, encoding: "utf-8", timeout });
    const out = `${r.stdout ?? ""}${r.stderr ?? ""}${r.error ? `\n${r.error.message}` : ""}`;
    return { code: r.status, out };
}

const SECRET_LINE =
    /(AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|(api[_-]?key|secret|token|passw(or)?d)\s*[:=]\s*['"][^'"\s]{8,}['"])/i;
// Strict pattern used as a commit guard (few false positives, e.g. fake passwords in tests)
const SECRET_STRICT = /^\+.*(AKIA[0-9A-Z]{16}|-----BEGIN [A-Z ]*PRIVATE KEY-----|ghp_[A-Za-z0-9]{30,}|sk-[A-Za-z0-9]{32,})/m;

function runScanners(): string {
    const parts: string[] = [];
    const subdirs = readdirSync(WORKDIR)
        .map((n) => join(WORKDIR, n))
        .filter((p) => !SKIP_DIRS.has(basename(p)) && statSync(p).isDirectory());
    for (const d of [WORKDIR, ...subdirs]) {
        if (!existsSync(join(d, "package.json"))) continue;
        const r = sh("npm audit --omit=dev", d, 120_000);
        parts.push(`--- npm audit (${relative(WORKDIR, d) || "."}), exit ${r.code}\n${r.out.slice(0, 3000)}`);
    }
    const hits = listSource().flatMap((f) =>
        readFileSync(f, "utf-8")
            .split("\n")
            .map((l, i) => (SECRET_LINE.test(l) ? `${relative(WORKDIR, f)}:${i + 1}` : ""))
            .filter(Boolean),
    );
    parts.push(`--- secret scan\n${hits.length ? hits.join("\n") : "no matches"}`);
    if (existsSync(join(WORKDIR, ".env"))) parts.push("--- WARNING: a .env file exists in the project root");
    return parts.join("\n\n");
}

/* ───────────────────────────── Git (script, LLM only writes messages) ───────────────────────────── */

const git = (...args: string[]) =>
    execFileSync("git", args, { cwd: WORKDIR, encoding: "utf-8", stdio: ["ignore", "pipe", "pipe"] }).trim();
const tryGit = (...args: string[]) => {
    try {
        return git(...args);
    } catch {
        return "";
    }
};

const FALLBACK_MSG: Record<string, string> = {
    architecture: "docs(architecture): add architecture and API contracts",
    backend: "feat(backend): implement backend",
    frontend: "feat(frontend): implement frontend",
    "security fix": "fix(security): address audit findings",
    tests: "test(qa): add automated tests and QA report",
};

async function commitMessage(phase: string, items: string): Promise<string> {
    try {
        const r = await llm.invoke([["system", AgentGIT], ["user", `Phase: ${phase}\nChanged files:\n${items}`]]);
        const first = String(r.content)
            .split("\n")
            .map((l) => l.replace(/^[`"'\s]+|[`"'\s]+$/g, ""))
            .find(Boolean);
        if (first && /^(feat|fix|docs|test|chore)(\([a-z-]+\))?: .+/.test(first)) return first.slice(0, 72);
    } catch {
        /* fall through */
    }
    return FALLBACK_MSG[phase] ?? `chore: ${phase}`;
}

async function commitPhase(phase: string, forcedMessage?: string): Promise<string> {
    git("add", "-A");
    const files = git("diff", "--cached", "--name-only").split("\n").filter(Boolean);
    if (files.length === 0) return "nothing to commit";
    const envLeak = files.some((f) => /(^|\/)\.env(\.|$)/.test(f) && !f.endsWith(".env.example"));
    if (envLeak || SECRET_STRICT.test(git("diff", "--cached", "-U0"))) {
        git("reset");
        throw new Error(`Secret detected before commit (${phase}); commit aborted, files unstaged.`);
    }
    const msg = forcedMessage ?? (await commitMessage(phase, files.join("\n")));
    git("commit", "-m", msg);
    log(`commit: ${msg}`);
    return msg;
}

/* ───────────────────────────── Agent call + payload parsing ───────────────────────────── */

function balancedObject(text: string, start: number): string | null {
    let depth = 0;
    let inStr = false;
    let esc = false;
    for (let i = start; i < text.length; i++) {
        const c = text.charAt(i);
        if (inStr) {
            if (esc) esc = false;
            else if (c === "\\") esc = true;
            else if (c === '"') inStr = false;
            continue;
        }
        if (c === '"') inStr = true;
        else if (c === "{") depth++;
        else if (c === "}") {
            depth--;
            if (depth === 0) return text.slice(start, i + 1);
        }
    }
    return null;
}

// Last JSON object having a string "status", wherever it is in the answer
function extractPayload(text: string): Payload | null {
    const starts: number[] = [];
    for (let i = text.length - 1; i >= 0 && starts.length < 60; i--) if (text.charAt(i) === "{") starts.push(i);
    for (const i of starts) {
        const json = balancedObject(text, i);
        if (!json) continue;
        try {
            const o = JSON.parse(json) as Record<string, unknown>;
            if (typeof o.status === "string") {
                return { status: o.status, defects: Array.isArray(o.defects) ? (o.defects as Defect[]) : [] };
            }
        } catch {
            /* try the previous candidate */
        }
    }
    return null;
}

// Agent call that must end with a valid status; retries once, then fails loudly (never a silent stop)
async function runAgent(name: string, system: string, user: string, valid: string[]) {
    for (let attempt = 1; attempt <= 2; attempt++) {
        log(`${name}: running (attempt ${attempt})`);
        const r = await llm.invoke([["system", `${system}\n\n${OUTPUT_RULES}`], ["user", user]]);
        const text = String(r.content);
        const payload = extractPayload(text);
        if (payload && valid.includes(payload.status)) {
            const written = writeFilesFromOutput(text);
            log(`${name}: ${payload.status}, ${written.length} file(s) written`);
            return { payload, written };
        }
        log(`${name}: missing or invalid status JSON`);
    }
    throw new Error(`${name}: no valid status after 2 attempts (expected one of ${valid.join(", ")})`);
}

// Agent call that only produces files (no status expected)
async function runFiles(name: string, system: string, user: string): Promise<string[]> {
    log(`${name}: running (files only)`);
    const r = await llm.invoke([["system", `${system}\n\n${OUTPUT_RULES}`], ["user", user]]);
    const written = writeFilesFromOutput(String(r.content));
    log(`${name}: ${written.length} file(s) written`);
    return written;
}

/* ───────────────────────────── Loop control ───────────────────────────── */

function nodeFor(t?: string): string | null {
    const s = (t ?? "").toLowerCase();
    if (s.includes("backend")) return "agentBackend";
    if (s.includes("frontend")) return "agentFrontend";
    if (s.includes("architect")) return "agentArchitect";
    return null;
}

// Rejection: +1 iteration, route to the first defect's owner, escalate (END) at 3 or if no owner
function reject(s: S, p: Payload, who: string) {
    const iteration = s.iteration + 1;
    const route = nodeFor(p.defects.find((d) => nodeFor(d.target_agent))?.target_agent);
    if (iteration >= MAX_REJECTIONS || !route) {
        const why = !route ? "no valid target agent" : `${MAX_REJECTIONS} rejections reached`;
        log(`ESCALATION to human (${who}: ${p.status}, ${why})`);
        return {
            status: p.status, defects: p.defects, iteration, route: "END", remediationTarget: "none",
            logs: [`${who} ${p.status} -> HUMAN_ESCALATION (${why})`],
        };
    }
    log(`${who} ${p.status} (rejection ${iteration}/${MAX_REJECTIONS}) -> ${route}`);
    return {
        status: p.status, defects: p.defects, iteration, route,
        remediationTarget: route.replace("agent", ""),
        logs: [`${who} ${p.status} -> ${route}`],
    };
}

const defectsFor = (s: S, node: string) => s.defects.filter((d) => nodeFor(d.target_agent) === node);
const defectsBlock = (l: Defect[]) => (l.length ? `\nDEFECTS:\n${JSON.stringify(l, null, 2)}\n` : "");
function reportFor(status: string): string {
    if (status === "SECURITY_REJECTED") return readDocs(["docs/CYBER_REPORT.md"]);
    if (status === "QA_REJECTED" || status === "QA_BLOCKED") return readDocs(["docs/QA_REPORT.md"]);
    if (status === "REJECTED") return readDocs(["docs/PO_REVIEW.md"]);
    return "";
}
const toArchitect = (p: Payload): Payload => ({
    ...p,
    defects: p.defects.map((d) => ({ ...d, target_agent: "Architect" })),
});

/* ───────────────────────────── Nodes ───────────────────────────── */

const agentPO = async (s: S) => {
    const prevScope = s.humanFeedback ? `${readDocs(["docs/SCOPE.md"])}\n\n` : "";
    const dynamicFeedback = s.humanFeedback ? `\n\nHUMAN FEEDBACK ON THE PREVIOUS SCOPE (apply it):\n${s.humanFeedback}` : "";
    const user = `${prevScope}User request:\n${s.input}${dynamicFeedback}\n\nMODE: SCOPE`;
    await runAgent("PO", AgentPO, user, ["WAITING_HUMAN_VALIDATION"]);
    return { logs: ["agentPO done"] };
};

// Pause: nothing with side effects before interrupt() (the node re-runs on resume)
const humanValidation = async (s: S) => {
    const d = interrupt({
        message: "Review docs/SCOPE.md. Resume with { approved: boolean, feedback?: string }",
        scope: readDocs(["docs/SCOPE.md"], 20000),
    }) as { approved?: boolean; feedback?: string } | undefined;
    if (d?.approved) return { route: "agentGitInit", humanFeedback: "", logs: ["scope approved"] };
    return { route: "agentPO", humanFeedback: d?.feedback ?? "Revise the scope.", logs: ["scope sent back to PO"] };
};

const agentGitInit = async (s: S) => {
    if (!existsSync(join(WORKDIR, ".git"))) git("init");
    if (git("status", "--porcelain")) throw new Error("Git INIT: working tree is not clean.");
    const gi = join(WORKDIR, ".gitignore");
    const current = existsSync(gi) ? readFileSync(gi, "utf-8") : "";
    const missing = ["node_modules/", ".env", ".env.*", "!.env.example"].filter((l) => !current.split("\n").includes(l));
    if (missing.length) appendFileSync(gi, `${current && !current.endsWith("\n") ? "\n" : ""}${missing.join("\n")}\n`);
    const slug = s.input.toLowerCase().replace(/[^a-z0-9]+/g, "-").split("-").filter(Boolean).slice(0, 4).join("-") || "task";
    const branch = `feature/${slug}-${Date.now().toString(36)}`;
    git("checkout", "-b", branch);
    log(`branch: ${branch}`);
    return { logs: [`agentGitInit: ${branch}`] };
};

const agentArchitect = async (s: S) => {
    const fix = s.remediationTarget === "Architect";
    const staticDocs =
        readDocs(["docs/SCOPE.md"]) +
        (fix ? `\n\n${readDocs(["docs/ARCHITECTURE.md", "docs/API_CONTRACTS.md"])}\n\n${reportFor(s.status)}` : "");
    const dynamicPayload = fix ? defectsBlock(s.defects) : "";
    const user = `${staticDocs}${dynamicPayload ? `\n${dynamicPayload}` : ""}`;
    await runAgent("Architect", AgentArchitect, user, ["ARCHITECTURE_COMPLETE"]);
    await commitPhase("architecture");
    return { status: "ARCHITECTURE_COMPLETE", logs: ["agentArchitect done"] };
};

const devNode = (name: "Backend" | "Frontend", system: string) => async (s: S) => {
    const node = `agent${name}`;
    const own = s.remediationTarget === name;
    const archChange = s.remediationTarget === "Architect";
    const wasSecurity = s.status === "SECURITY_REJECTED";
    const staticDocs =
        readDocs(["docs/SCOPE.md", "docs/ARCHITECTURE.md", "docs/API_CONTRACTS.md"]) +
        (own ? `\n\n${reportFor(s.status)}` : "");
    const dynamicParts: string[] = [];
    if (own) {
        const b = defectsBlock(defectsFor(s, node));
        if (b) dynamicParts.push(b.trim());
    }
    if (archChange) {
        dynamicParts.push("NOTE: docs/ARCHITECTURE.md and docs/API_CONTRACTS.md were amended (see Change Log). Align the code with them.");
    }
    const user = staticDocs + (dynamicParts.length ? `\n\n${dynamicParts.join("\n\n")}` : "");
    const { payload } = await runAgent(name, system, user, ["DEVELOPMENT_COMPLETE", "CONTRACT_BLOCKED"]);
    if (payload.status === "CONTRACT_BLOCKED") return reject(s, toArchitect(payload), name);
    await commitPhase(own && wasSecurity ? "security fix" : name.toLowerCase());
    // Backend fix -> straight to Cyber; otherwise Backend -> Frontend -> Cyber
    const route = name === "Frontend" || own ? "agentCyber" : "agentFrontend";
    return { status: "DEVELOPMENT_COMPLETE", route, logs: [`${node} done`] };
};
const agentBackend = devNode("Backend", AgentBackend);
const agentFrontend = devNode("Frontend", AgentFrontend);

const agentCyber = async (s: S) => {
    const user =
        `${readDocs(["docs/ARCHITECTURE.md", "docs/API_CONTRACTS.md"])}\n\n=== SOURCE CODE ===\n${readSource()}\n\n` +
        `=== SCANNER OUTPUT ===\n${runScanners()}` +
        (s.defects.length ? `\n\nPREVIOUS DEFECTS (state FIXED / NOT FIXED for each):\n${JSON.stringify(s.defects, null, 2)}` : "");
    const { payload } = await runAgent("Cyber", AgentCyber, user, ["CYBER_COMPLETE", "SECURITY_REJECTED"]);
    if (payload.status === "SECURITY_REJECTED") return reject(s, payload, "Cyber");
    return { status: "CYBER_COMPLETE", defects: [], remediationTarget: "none", route: "agentQaTests", logs: ["agentCyber done"] };
};

const agentQaTests = async (s: S) => {
    const base = `${readDocs(["docs/SCOPE.md", "docs/API_CONTRACTS.md", "docs/ARCHITECTURE.md"])}\n\n=== SOURCE CODE ===\n${readSource()}`;
    const tests = await runFiles(
        "QA (write tests)",
        AgentQaTests,
        `${base}\n\nPHASE 1 of 2: write ONLY the test files now. No report, no status JSON.`
    );
    const exec = sh(TEST_COMMAND, WORKDIR);
    log(`tests: exit code ${exec.code}`);
    const staticContext = `${readDocs(["docs/SCOPE.md"])}\n\n${readDocs(tests, 3000)}`;
    const dynamicInstructions =
        `=== TEST EXECUTION (command: ${TEST_COMMAND}, exit code: ${exec.code}) ===\n${exec.out.slice(-6000)}\n\n` +
        `PHASE 2 of 2: the tests above were written and executed by the orchestrator. ` +
        `Write docs/QA_REPORT.md from these REAL results and finish with the JSON status.`;
    const user = `${staticContext}\n\n${dynamicInstructions}`;
    const res = await runAgent("QA (report)", AgentQaTests, user, ["QA_COMPLETE", "QA_REJECTED", "QA_BLOCKED"]);
    let payload = res.payload;
    // Deterministic guard: never accept QA_COMPLETE if the test command did not exit 0
    if (payload.status === "QA_COMPLETE" && exec.code !== 0) {
        payload =
            exec.code === null
                ? { status: "QA_BLOCKED", defects: [] }
                : { status: "QA_REJECTED", defects: [{ id: "QX", severity: "Blocker", target_agent: "Backend", summary: `Test command exited with code ${exec.code}` }] };
        log(`QA: overridden to ${payload.status} (exit code ${exec.code})`);
    }
    await commitPhase("tests");
    if (payload.status === "QA_COMPLETE") {
        return { status: "QA_COMPLETE", defects: [], route: "agentPO_review", logs: ["agentQaTests done"] };
    }
    return reject(s, payload, "QA");
};

const agentPO_review = async (s: S) => {
    const docs = readDocs(["docs/SCOPE.md", "docs/QA_REPORT.md", "docs/CYBER_REPORT.md", "docs/BACKEND_SUMMARY.md", "docs/FRONTEND_SUMMARY.md"]);
    const user = `${docs}\n\nMODE: REVIEW`;
    const { payload } = await runAgent("PO review", AgentPO, user, ["VALIDATED", "REJECTED"]);
    if (payload.status === "REJECTED") return reject(s, payload, "PO");
    return { status: "VALIDATED", defects: [], route: "agentGitFinalize", logs: ["PO validated"] };
};

const agentGitFinalize = async (s: S) => {
    const lastTag = tryGit("describe", "--tags", "--abbrev=0");
    const subjects = git("log", lastTag ? `${lastTag}..HEAD` : "HEAD", "--pretty=%s");
    let version = "v1.0.0";
    if (lastTag) {
        const m = lastTag.match(/^v(\d+)\.(\d+)\.(\d+)$/);
        if (!m) throw new Error(`Git FINALIZE: last tag "${lastTag}" is not SemVer (vX.Y.Z).`);
        const [maj, min, pat] = [Number(m[1]), Number(m[2]), Number(m[3])];
        version = /^feat/m.test(subjects) ? `v${maj}.${min + 1}.0` : `v${maj}.${min}.${pat + 1}`;
    }
    const r = await llm.invoke([["system", AgentGIT], ["user", `Phase: release\nChanged files:\n${subjects}`]]);
    const lines = String(r.content).split("\n").map((l) => l.trim());
    const first = lines.find(Boolean) ?? "";
    const subject = /^(feat|fix|docs|test|chore)(\([a-z-]+\))?: .+/.test(first) ? first.slice(0, 72) : `chore(release): ${version}`;
    const notes = lines.slice(lines.indexOf(first) + 1).filter(Boolean).join("\n") || subjects.split("\n").map((l) => `- ${l}`).join("\n");
    const date = new Date().toISOString().slice(0, 10);
    mkdirSync(join(WORKDIR, "docs"), { recursive: true });
    writeFileSync(join(WORKDIR, "docs/RELEASE_NOTES.md"), `# Release ${version}\n\n- Branch: ${git("branch", "--show-current")}\n- Date: ${date}\n\n${notes}\n`);
    const cl = join(WORKDIR, "CHANGELOG.md");
    writeFileSync(cl, `## ${version} - ${date}\n\n${notes}\n\n${existsSync(cl) ? readFileSync(cl, "utf-8") : ""}`);
    await commitPhase("release", subject);
    git("tag", "-a", version, "-m", version);
    log(`tag ${version} created (no merge: left to the human)`);
    return { logs: [`agentGitFinalize: ${version}`] };
};

// Final sign-off (single pause mechanism: interrupt only)
const finalHumanValidation = async (_s: S) => {
    interrupt({ message: "Release ready — final human approval (merge is up to you)" });
    return { logs: ["finalHumanValidation done"] };
};

/* ───────────────────────────── Graph ───────────────────────────── */

const routeFromState = (s: S): string => (!s.route || s.route === "END" ? END : s.route);

const memory = new MemorySaver();

const graph = new StateGraph(State)
    .addNode("agentPO", agentPO)
    .addNode("humanValidation", humanValidation)
    .addNode("agentGitInit", agentGitInit)
    .addNode("agentArchitect", agentArchitect)
    .addNode("agentBackend", agentBackend)
    .addNode("agentFrontend", agentFrontend)
    .addNode("agentCyber", agentCyber)
    .addNode("agentQaTests", agentQaTests)
    .addNode("agentPO_review", agentPO_review)
    .addNode("agentGitFinalize", agentGitFinalize)
    .addNode("finalHumanValidation", finalHumanValidation)

    .addEdge(START, "agentPO")
    .addEdge("agentPO", "humanValidation")
    .addConditionalEdges("humanValidation", routeFromState, {
        agentGitInit: "agentGitInit",
        agentPO: "agentPO",
    })
    .addEdge("agentGitInit", "agentArchitect")
    .addEdge("agentArchitect", "agentBackend")

    // Backend: initial -> Frontend; own fix -> Cyber; CONTRACT_BLOCKED -> Architect
    .addConditionalEdges("agentBackend", routeFromState, {
        agentFrontend: "agentFrontend",
        agentCyber: "agentCyber",
        agentArchitect: "agentArchitect",
        [END]: END,
    })
    .addConditionalEdges("agentFrontend", routeFromState, {
        agentCyber: "agentCyber",
        agentArchitect: "agentArchitect",
        [END]: END,
    })
    .addConditionalEdges("agentCyber", routeFromState, {
        agentQaTests: "agentQaTests",
        agentBackend: "agentBackend",
        agentFrontend: "agentFrontend",
        agentArchitect: "agentArchitect",
        [END]: END,
    })
    .addConditionalEdges("agentQaTests", routeFromState, {
        agentPO_review: "agentPO_review",
        agentBackend: "agentBackend",
        agentFrontend: "agentFrontend",
        agentArchitect: "agentArchitect",
        [END]: END,
    })
    .addConditionalEdges("agentPO_review", routeFromState, {
        agentGitFinalize: "agentGitFinalize",
        agentBackend: "agentBackend",
        agentFrontend: "agentFrontend",
        agentArchitect: "agentArchitect",
        [END]: END,
    })
    .addEdge("agentGitFinalize", "finalHumanValidation")
    .addEdge("finalHumanValidation", END);

export const app = graph.compile({ checkpointer: memory });